/* eslint-disable no-console */
import { fileURLToPath } from 'node:url';

import { Pool as NeonPool, neonConfig } from '@neondatabase/serverless';
import { drizzle as drizzleNeon } from 'drizzle-orm/neon-serverless';
import { migrate as migrateNeon } from 'drizzle-orm/neon-serverless/migrator';
import { drizzle as drizzlePg } from 'drizzle-orm/node-postgres';
import { migrate as migratePg } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';
import ws from 'ws';

import { loadConfig } from '../../config/env.js';

/** Folder with the SQL files generated by `npm run db:generate`. */
const migrationsFolder = fileURLToPath(new URL('../../../drizzle', import.meta.url));

/**
 * Applies pending migrations. Uses MIGRATION_DATABASE_URL when set: on Neon
 * that should be the direct (unpooled) connection string.
 */
async function main(): Promise<void> {
  const config = loadConfig();
  const url = config.database.migrationUrl;
  console.log(`Applying migrations from ${migrationsFolder} (${config.database.driver})...`);

  if (config.database.driver === 'neon') {
    neonConfig.webSocketConstructor = ws;
    const pool = new NeonPool({ connectionString: url, max: 1 });
    try {
      await migrateNeon(drizzleNeon({ client: pool }), { migrationsFolder });
    } finally {
      await pool.end();
    }
  } else {
    const pool = new pg.Pool({ connectionString: url, max: 1 });
    try {
      await migratePg(drizzlePg({ client: pool }), { migrationsFolder });
    } finally {
      await pool.end();
    }
  }
  console.log('Migrations applied.');
}

main().catch((error: unknown) => {
  console.error('Migration failed:', error);
  process.exit(1);
});
